on conflict(game_id,category_id) do update set label=excluded.label,target_count=excluded.target_count,sort_order=excluded.sort_order,enabled=true,updated_at=now();

on conflict(id) do update set lifecycle_status='active',published_version=1,updated_at=now();

on conflict(item_id,version) do nothing;

on conflict(item_id,game_id,category_id) do update set enabled=true,sort_order=excluded.sort_order;

update public.content_releases set status='superseded' where game_id='bad-advice-only' and status='published';
on conflict(release_id,item_id) do nothing;
